"""Build a printable design document. Source PNGs are embedded by reference,
not retouched, rescaled on disk, or claimed to be model renders."""
from pathlib import Path
import json,html,runpy
clean=runpy.run_path(str(Path(__file__).with_name('text-cleanup.py')))['clean']
r=Path(__file__).resolve().parents[1];spec=json.loads((r/'specification/design-spec.json').read_text())
head='''<!doctype html><html lang="vi"><meta charset="utf-8"><title>BUM07 P5.2 — Character Design Specification</title><style>
@page{size:A4 landscape;margin:10mm}*{box-sizing:border-box}body{margin:0;font:10.5pt 'DejaVu Sans',Arial,sans-serif;color:#182b45;background:white}h1{font-size:24pt;margin:0 0 5mm}h2{font-size:17pt;margin:0 0 3mm}h3{font-size:12pt;margin:3mm 0}p{line-height:1.38;margin:2mm 0}table{width:100%;border-collapse:collapse;font-size:9pt;margin:3mm 0}td,th{border:1px solid #ccd6de;padding:2.3mm;vertical-align:top}th{background:#edf2f6}section{break-after:page;min-height:180mm}section:last-child{break-after:auto}.tag{display:inline-block;padding:2mm 3mm;background:#fff1b8;font-weight:bold}.muted{font-size:8.5pt;color:#526474}.pair{display:flex;justify-content:center;gap:12mm;height:153mm}.pair figure{margin:0;text-align:center;width:108mm}.pair img{height:146mm;max-width:108mm;object-fit:contain}.pair figcaption{font-size:9pt}.diagram{display:block;max-width:100%;height:145mm;object-fit:contain;margin:auto}.measure{height:128mm;width:100%;object-fit:contain}.stop{background:#fff1b8;padding:3mm;border-left:2mm solid #cc9c17;margin:4mm 0}li{margin:2mm 0;line-height:1.4}html[data-book=turnaround] .expression{display:none}html[data-book=expressions] .turnaround{display:none}
</style><script>document.documentElement.dataset.book=new URLSearchParams(location.search).get('book')||'all';</script><body>'''
pages=[]
def page(book,body):pages.append(f'<section class="{book}">{body}</section>')
def pair(book,title,subtitle,items,foot):
 body=f'<h2>{title}</h2><p class="muted">{subtitle}</p><div class="pair">'
 for file,label in items:body+=f'<figure><img src="{file}" alt="{label}"><figcaption>{label}</figcaption></figure>'
 page(book,body+'</div><p class="muted">'+foot+'</p>')
page('turnaround','''<h1>BUM07 · P5.2<br>Turnaround &amp; Construction Specification</h1><p class="tag">B / FIELD BREEZE ĐÃ ĐƯỢC CHỌN · SPEC P5.2 CHỜ NGHIỆM THU</p><p>Nguồn P5.1: commit35997cc. Chỉ dùng nhận diện B: mặt oval mềm, mắt hạnh nhân, tóc ngắn rẽ lệch thấp, áo vàng07, navy, tất sáng và giày bóng đá.</p><div class="stop"><b>Chỉ tài liệu thiết kế. Chưa được phép triển khai Blender.</b><br>Ảnh AI concept, không phải render Blender hoặc bằng chứng có model3D. Không tự công bố9/10.</div><h3>Bộ bàn giao</h3><ul><li>6PNG turnaround riêng:0°,45°,90°,180°, A-pose và cận mặt neutral.</li><li>16PNG biểu cảm riêng trong PDF biểu cảm:8trạng thái×2góc.</li><li>Bảng tỷ lệH/CSV/JSON, màu và cấu trúc tóc–mắt–miệng–trang phục.</li><li>Báo cáo nhất quán, điểm còn phải chốt và tiêu chí PASS/FAIL.</li></ul><p><b>H là chiều cao sọ–cằm neutral, không tính tóc.</b> 5H từ sọ đến đất và tối đa5,2H tính tóc là đề xuất, chưa đo từ mesh. PNG gốc1024×1536; không nội suy phóng lớn.</p><p class="muted">Không sửa main, Pages, Supabase, PR#2, ba nhân vật khác hoặc các bản lịch sử. Không dựng mesh/rig/GLB sản xuất trong P5.2.</p>''')
page('turnaround','''<h2>Bố cục mốc đo chung — không phải camera đã kiểm chứng</h2><p>Các PNG giữ nguyên1024×1536, đặt1:1 rồi phủ thướcH <b>đề xuất</b>; không kéo giãn từng ảnh để che chênh lệch.</p><img class="measure" src="specification/turnaround-measurement-layout.svg"><p class="muted">Đất tài liệu y1408, đỉnh sọ đề xuất y96,1H262,4px. Sọ bị tóc che nên không được coi thước này là phép đo giải phẫu từ ảnh. Các góc là ý đồ orthographic-style, chưa có mesh/camera thật. Xem từng ảnh lớn ở các trang sau.</p>''')
pair('turnaround','Turnaround · Chính diện0° / Góc45°','Cùng dáng đứng; góc45 nhìn từ bên phải giải phẫu, mũi hướng phải trang.',[('turnaround/01-front-000.png','0° · mốc nhận diện P5.2'),('turnaround/02-three-quarter-045.png','45° · diễn giải cùng khối')],'Ảnh AI design-only; số đo bảng là đề xuất, không phải đo từ model.')
pair('turnaround','Turnaround · Nghiêng90° / Sau lưng180°','Sau lưng/gáy/back07 là đề xuất mới cần chủ dự án duyệt riêng.',[('turnaround/03-profile-090.png','90° · nghiêng bên phải'),('turnaround/04-back-180.png','180° · sau lưng')],'Ngôi ở trái nhân vật; không mirror ảnh để làm phía còn lại. CổV chỉ ở trước, sau là cổbo.')
pair('turnaround','A-pose / Cận mặt neutral','A-pose35° là ý đồ tư thế thiết kế, không phải rig. Cận neutral dùng chung byte với biểu cảmNeutral0°.',[('turnaround/05-a-pose-000.png','A-pose · không đổi tỷ lệ theo khung'),('turnaround/06-neutral-face-000.png','Neutral0° · mốc biểu cảm')],'Giữ bàn tay năm ngón; mắt hạnh nhân và oval đầu của B, không đổi sangScott/A/C.')
body='''<h2>Bảng tỷ lệ đề xuất — chưa có mesh để đo</h2><table><tr><th>Mốc</th><th>Đề xuấtH</th><th>Ý nghĩa</th></tr>'''
for name,val,note in [('Sọ–cằm / sọ–đất','1,00 /5,00','Không tính phần tóc nhô'),('Rộng / sâu sọ','0,74 /0,78','Chưa tính tai và nhô mũi'),('Tâm vai / hông / gối / cổ chân','3,85 /2,55 /1,50 /0,28','Cao từ đất'),('Tay trên / cẳng tay / bàn tay','0,82 /0,65 /0,44','Dài theo chi'),('Đùi / cẳng chân','1,05 /1,22','Từ tâm khớp'),('Rộng khe mắt / đường kínhglobe / iris','0,19 /0,22 /0,10','Tâm mắt cách nhau0,32H'),('Miệng neutral','0,34','Không dùng smile thayrest'),('Cạp quần / gấu áo','2,48 /2,43','Đề xuất áo che cạp'),('Số07 trước: cao / rộng','0,38 /0,50','TâmZ~3,33H'),('Dài / rộng giày','0,82 /0,34','Không đo dài giày ởgóc0°')]:body+=f'<tr><td>{name}</td><td>{val}</td><td>{note}</td></tr>'
body+='''</table><p class="muted">Bảng đầy đủ: specification/body-landmarks.csv,proportions.csv,design-spec.json. Không khóa chiều cao thật bằngmét, LOD, texture resolution hoặc ngân sáchGPU ởgiai đoạn này.</p>''';page('turnaround',body)
page('turnaround','''<h2>Cấu trúc mặt — sơ đồ2D đề xuất</h2><img class="diagram" src="specification/face-construction-guide.svg"><p class="muted">Giữ globe vàsocket ổn định, vành mí cóchiều dày, khóe cómô nối; môi/khóe/má cóthể tích. Răng trên theo hàm trên, răng dưới/lưỡi theo hàm dưới. Chưa có wireframe/rig hoặc contact test.</p>''')
